    self.assertEqual(_parse_size_to_bytes("abc"), 0)
    self.assertEqual(_parse_size_to_bytes("10XY"), 0)

def test_cp_disabled_has_no_cp_suffix(self):
    b = self.make_backend(attn_cp_size=1, attn_cp_rank=0)
    self.assertNotIn("_cp", b.config_suffix)

def test_zero_hash(self):
    result = hash_str_to_int64("0" * 64)
    self.assertEqual(result, 0)

def test_small_positive_value(self):
    result = hash_str_to_int64("0000000000000001" + "0" * 48)
    self.assertEqual(result, 1)

def test_large_positive_value(self):
    result = hash_str_to_int64("7fffffffffffffff" + "0" * 48)
    self.assertEqual(result, 2**63 - 1)

def test_negative_overflow(self):
    result = hash_str_to_int64("8000000000000000" + "0" * 48)
    self.assertEqual(result, -(2**63))

def test_max_unsigned_maps_to_minus_one(self):
    result = hash_str_to_int64("f" * 16 + "0" * 48)
    self.assertEqual(result, -1)

def test_none_input_returns_none_tuple(self):
    result = split_node_hash_value(None, 10, 4)
    self.assertEqual(result, (None, None))

def test_total_length_preserved(self):
    hash_values = [f"h_{i}" for i in range(10)]
    for split_len in [0, 1, 3, 5, 7, 9, 10]:
        for page_size in [1, 2, 4]:
            new_hash, child_hash = split_node_hash_value(
                hash_values, split_len, page_size
            )
            self.assertEqual(
                len(new_hash) + len(child_hash),
                len(hash_values),
                f"split_len={split_len}, page_size={page_size}",
            )

def test_kv_cache_events(self):
    """Test KV cache events functionality."""
    test_cases = [
        (1, True),
        (2, True),
        (1, False),
    ]

    for page_size, enable_events in test_cases:
        with self.subTest(page_size=page_size, enable_events=enable_events):
            cache = RadixCache.create_simulated(
                page_size=page_size, enable_kv_cache_events=enable_events
            )

            # Insert data
            cache.insert(
                InsertParams(key=RadixKey(array("q", [1, 2, 3, 4, 5])), value=None)
            )

            # Take events
            events = cache.take_events()

            if enable_events:
                self.assertGreater(len(events), 0)
                # Verify events include BlockStored events (there might be other event types)
                block_stored_events = [
                    e for e in events if isinstance(e, BlockStored)
                ]
                self.assertGreater(len(block_stored_events), 0)
                for event in block_stored_events:
                    self.assertLessEqual(len(event.token_ids), page_size)
            else:
                self.assertEqual(len(events), 0)

def test_unknown_combo_raises(self):
    from sglang.srt.mem_cache.deepseek_v4_memory_pool import (
        DeepSeekV4TokenToKVPool,
    )
    from sglang.srt.mem_cache.swa_memory_pool import SWAKVPool

    for cls in (SWAKVPool, DeepSeekV4TokenToKVPool):
        kvcache = _mock_kvcache(cls)
        with self.assertRaises(AssertionError) as cm:
            _select_strategy(kvcache, {FULL})
        self.assertIn("No matching HiCache strategy", str(cm.exception))

def test_context_manager_releases(self):
    """Test that exiting the context manager releases all penalizers."""
    reqs = [_make_req(freq=1.0)]
    batch = _make_batch(reqs)
    with BatchedPenalizerOrchestrator(
        VOCAB_SIZE, batch, {BatchedFrequencyPenalizer}
    ) as orch:
        self.assertTrue(orch.is_required)
    self.assertFalse(orch.is_required)
    self.assertEqual(len(orch.penalizers), 0)

def test_blocks_additional_stop_tokens(self):
    """Test that tokenizer's additional_stop_token_ids are also blocked."""
    req = _make_req(min_tokens=3, stop_ids=None, eos_id=2)
    req.tokenizer.additional_stop_token_ids = {7, 8}
    batch = _make_batch([req])
    orch = BatchedPenalizerOrchestrator(
        VOCAB_SIZE, batch, {BatchedMinNewTokensPenalizer}
    )
    pen = orch.penalizers[BatchedMinNewTokensPenalizer]

    logits = torch.zeros(1, VOCAB_SIZE)
    pen.apply(logits)
    # EOS (2) + additional stops (7, 8) should all be blocked
    for tok in [2, 7, 8]:
        self.assertTrue(
            torch.isinf(logits[0, tok]) and logits[0, tok] < 0,
            f"token {tok} should be blocked before min_new_tokens",
        )
    # Non-stop tokens should be fine
    self.assertEqual(logits[0, 0].item(), 0.0)

